import React, { useState } from 'react';

// CSS 파일은 AdminPage.css를 사용한다고 했으니 별도의 import는 필요 없어!
// import './AccountInfoTab.css'; 

const AccountInfoTab = ({ adminInfo }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    ...adminInfo,
    password: '',
    confirmPassword: '',
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleDuplicateCheck = (field) => {
    // 실제 백엔드 중복 확인 API 호출 로직
    alert(`${formData[field]}은(는) 사용 가능합니다! ✅ (API 연동 필요)`);
    console.log(`${field} 중복 확인:`, formData[field]);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (formData.password !== formData.confirmPassword) {
      alert('비밀번호와 비밀번호 확인이 일치하지 않아! 다시 확인해줘! 😵‍💫');
      return;
    }
    // 실제 백엔드 관리자 계정 정보 수정 API 호출 로직
    alert('관리자 계정 정보가 성공적으로 수정되었습니다! 🥳 (API 연동 필요)');
    console.log('수정된 관리자 정보:', formData);
    setIsEditing(false);
  };

  return (
    <div className="tab-content-section account-info-tab">
      <h3 className="tab-content-title">계정 정보 {!isEditing ? '보기' : '수정'}</h3>

      {!isEditing ? (
        <>
          {/* 정보 보기: 기존과 동일 (아이디, 닉네임, 이메일) */}
          <div className="info-item view-mode">
            <span className="info-label">아이디</span>
            <span className="info-value">{adminInfo.id}</span>
          </div>
          <div className="info-item view-mode">
            <span className="info-label">닉네임</span>
            <span className="info-value">{adminInfo.role}</span>
          </div>
          <div className="info-item view-mode">
            <span className="info-label">이메일</span>
            <span className="info-value">{adminInfo.email}</span>
          </div>
          <div className="button-group" style={{ display: 'flex', justifyContent: 'center', gap: '15px', marginTop: '40px' }}>
            <button className="action-button" onClick={() => setIsEditing(true)}>정보 수정 ✏️</button>
          </div>
        </>
      ) : (
        <form onSubmit={handleSubmit}>
          {/* 정보 수정 폼: 이름 필드 제거, 닉네임 -> 이메일 순서 변경, 정렬 통일! */}
          
          {/* 닉네임 필드 (중복확인 버튼 포함) - 이메일보다 위로 이동! */}
          <div className="info-item input-with-button edit-mode"> {/* edit-mode 클래스 추가 */}
            <label className="info-label" htmlFor="adminRole">닉네임</label>
            <input
              type="text"
              id="adminRole"
              name="role"
              value={formData.role}
              onChange={handleChange}
              className="info-value-input"
              required
            />
            <button
              type="button"
              className="small-action-button"
              onClick={() => handleDuplicateCheck('role')}
            >
              중복확인
            </button>
          </div>

          {/* 이메일 필드 (중복확인 버튼 포함) */}
          <div className="info-item input-with-button edit-mode"> {/* edit-mode 클래스 추가 */}
            <label className="info-label" htmlFor="adminEmail">이메일</label>
            <input
              type="email"
              id="adminEmail"
              name="email"
              value={formData.email}
              onChange={handleChange}
              className="info-value-input"
              required
            />
            <button
              type="button"
              className="small-action-button"
              onClick={() => handleDuplicateCheck('email')}
            >
              중복확인
            </button>
          </div>

          {/* 비밀번호 필드 */}
          <div className="info-item edit-mode"> {/* edit-mode 클래스 추가 */}
            <label className="info-label" htmlFor="adminPassword">비밀번호</label>
            <input
              type="password"
              id="adminPassword"
              name="password"
              value={formData.password}
              onChange={handleChange}
              className="info-value-input"
              placeholder="새 비밀번호 입력"
            />
          </div>

          {/* 비밀번호 확인 필드 */}
          <div className="info-item edit-mode"> {/* edit-mode 클래스 추가 */}
            <label className="info-label" htmlFor="adminConfirmPassword">비밀번호 확인</label>
            <input
              type="password"
              id="adminConfirmPassword"
              name="confirmPassword"
              value={formData.confirmPassword}
              onChange={handleChange}
              className="info-value-input"
              placeholder="새 비밀번호 다시 입력"
            />
          </div>

          <div className="button-group" style={{ display: 'flex', justifyContent: 'center', gap: '15px', marginTop: '40px' }}>
            <button type="submit" className="action-button">저장 ✅</button>
            <button type="button" className="action-button secondary" onClick={() => setIsEditing(false)}>취소 ↩️</button>
          </div>
        </form>
      )}
    </div>
  );
};

export default AccountInfoTab;
